/**
 * @name PSM-Cleanup
 * @description Phase 4C RC Hotfix: lightweight legacy UI cleanup + startup branding.
 */
(function psmCleanupHotfix() {
  // PSM_PHASE5_2D_EARLY_STARTUP_BRAND
  // The inherited loading-screen CSS is inside the signed Pengu core.
  // Do not patch core.dll; override only the visible startup presentation.
  const PSM_EARLY_ICON = "data:image/png;base64,";

  function installEarlyStartupBrandOverride() {
    try {
      const id = "psm-early-startup-brand";
      if (document.getElementById(id)) return;
      const style = document.createElement("style");
      style.id = id;
      style.textContent = `
        div[id^="index_loading_div"] {
          background-color:#010a13 !important;
        }
        div[id^="index_loading_div"] > img {
          display:none !important;
          visibility:hidden !important;
        }
        div[id^="index_loading_div"]::before {
          content:"" !important;
          background-image:url("${PSM_EARLY_ICON}") !important;
          background-repeat:no-repeat !important;
          background-position:center !important;
          background-size:contain !important;
          image-rendering:auto !important;
          width:144px !important;
          height:144px !important;
          border-radius:24px !important;
        }
        div[id^="index_loading_div"]::after {
          margin-top:32px !important;
          content:"PERSONAL SKIN MANAGER" !important;
          color:#e2e1e1 !important;
          font-family:"Inter","Segoe UI",sans-serif !important;
          font-size:1rem !important;
          letter-spacing:.08em !important;
          text-transform:uppercase !important;
        }
      `;
      (document.head || document.documentElement).appendChild(style);
    } catch (e) {
      console.warn("[PSM-Cleanup] early startup branding override failed", e);
    }
  }

  installEarlyStartupBrandOverride();
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", installEarlyStartupBrandOverride, { once:true });
  }
  const POPUP_TARGET = "Hi Summoner, your League is now Unlocked!";
  const STARTUP_TEXT = "ROSE";
  const ACTIVE_FOR_MS = 45000;

  const observedRoots = new WeakSet();
  const observers = [];
  let stopped = false;

  function normalizedText(node) {
    try {
      return String(node?.textContent || "").replace(/\s+/g, " ").trim();
    } catch {
      return "";
    }
  }

  function psmIconUrl() {
    try {
      const port = window.__roseBridge?.port;
      return port ? `http://127.0.0.1:${port}/asset/icon.png` : "";
    } catch {
      return "";
    }
  }

  function removeLegacyPopupFrom(node) {
    if (!node) return false;
    const text = normalizedText(node);
    if (!text.includes(POPUP_TARGET)) return false;

    const selector = [
      '[role="dialog"]',
      'lol-uikit-dialog-frame',
      'lol-uikit-dialog',
      '[class*="dialog"]',
      '[class*="modal"]',
      '[class*="overlay"]'
    ].join(",");

    let candidate = null;
    try {
      candidate = node.closest?.(selector) || null;
    } catch {}

    if (!candidate) {
      let current = node;
      for (let depth = 0; current && depth < 12; depth += 1) {
        const currentText = normalizedText(current);
        if (
          currentText.includes(POPUP_TARGET) &&
          /Do not show again/i.test(currentText) &&
          /(OKAY|OK)/i.test(currentText)
        ) {
          candidate = current;
        }
        current = current.parentElement;
      }
    }

    if (candidate) {
      const candidateText = normalizedText(candidate);
      if (
        candidateText.includes(POPUP_TARGET) &&
        /Do not show again/i.test(candidateText) &&
        /(OKAY|OK)/i.test(candidateText)
      ) {
        candidate.remove();
        console.info("[PSM-Cleanup] removed inherited Rose community dialog");
        return true;
      }
    }

    return false;
  }

  function rebrandStartupSplashText(el) {
    if (!el || normalizedText(el) !== STARTUP_TEXT) return false;

    let rect = null;
    try { rect = el.getBoundingClientRect(); } catch {}
    if (rect && rect.width === 0 && rect.height === 0) return false;

    el.textContent = "PERSONAL SKIN MANAGER";
    el.setAttribute?.("data-psm-startup-brand", "true");

    let container = el.parentElement;
    for (let depth = 0; container && depth < 8; depth += 1) {
      let containerRect = null;
      try { containerRect = container.getBoundingClientRect(); } catch {}

      if (
        containerRect &&
        containerRect.width >= Math.min(500, window.innerWidth * 0.45) &&
        containerRect.height >= Math.min(300, window.innerHeight * 0.35)
      ) {
        break;
      }
      container = container.parentElement;
    }

    if (container) {
      const iconUrl = psmIconUrl();
      if (iconUrl) {
        let images = [];
        try { images = Array.from(container.querySelectorAll("img")); } catch {}

        const likelyLogo =
          images.find((img) => /rose|logo/i.test(String(img.src || ""))) ||
          images.find((img) => {
            try {
              const r = img.getBoundingClientRect();
              return r.width >= 90 && r.height >= 90 && r.width <= 400 && r.height <= 400;
            } catch {
              return false;
            }
          });

        if (likelyLogo) {
          likelyLogo.src = iconUrl;
          likelyLogo.alt = "Personal Skin Manager";
          likelyLogo.title = "Personal Skin Manager";
          likelyLogo.setAttribute("data-psm-startup-logo", "true");
        }
      }
    }

    console.info("[PSM-Cleanup] rebranded inherited ROSE startup splash");
    return true;
  }

  function inspectExisting(root) {
    if (!root) return;

    let candidates = [];
    try {
      candidates = root.querySelectorAll(
        'div,span,p,h1,h2,h3,label,strong,lol-uikit-dialog-frame,lol-uikit-dialog,[role="dialog"]'
      );
    } catch {}

    for (const candidate of candidates) {
      const text = normalizedText(candidate);
      if (text.includes(POPUP_TARGET)) {
        if (removeLegacyPopupFrom(candidate)) break;
      } else if (text === STARTUP_TEXT) {
        rebrandStartupSplashText(candidate);
      }
    }
  }

  function discoverShadowRoots(element) {
    if (!element || element.nodeType !== Node.ELEMENT_NODE) return;

    if (element.shadowRoot) {
      observeRoot(element.shadowRoot);
      inspectExisting(element.shadowRoot);
    }

    let descendants = [];
    try { descendants = element.querySelectorAll("*"); } catch {}
    for (const descendant of descendants) {
      if (descendant.shadowRoot) {
        observeRoot(descendant.shadowRoot);
        inspectExisting(descendant.shadowRoot);
      }
    }
  }

  function inspectElement(element) {
    if (!element || element.nodeType !== Node.ELEMENT_NODE) return;

    removeLegacyPopupFrom(element);
    rebrandStartupSplashText(element);

    let candidates = [];
    try {
      candidates = element.querySelectorAll(
        'div,span,p,h1,h2,h3,label,strong,lol-uikit-dialog-frame,lol-uikit-dialog,[role="dialog"]'
      );
    } catch {}

    for (const candidate of candidates) {
      const text = normalizedText(candidate);
      if (text.includes(POPUP_TARGET)) {
        if (removeLegacyPopupFrom(candidate)) break;
      } else if (text === STARTUP_TEXT) {
        rebrandStartupSplashText(candidate);
      }
    }

    discoverShadowRoots(element);
  }

  function observeRoot(root) {
    if (!root || observedRoots.has(root) || stopped) return;
    observedRoots.add(root);

    try {
      const observer = new MutationObserver((mutations) => {
        if (stopped) return;
        for (const mutation of mutations) {
          for (const node of mutation.addedNodes) {
            if (node.nodeType === Node.ELEMENT_NODE) {
              inspectElement(node);
            }
          }
        }
      });

      observer.observe(root, { childList: true, subtree: true });
      observers.push(observer);
    } catch {}
  }

  try {
    const originalAttachShadow = Element.prototype.attachShadow;
    if (!originalAttachShadow.__psmCleanupHotfixWrapped) {
      const wrappedAttachShadow = function(init) {
        const root = originalAttachShadow.call(this, init);
        observeRoot(root);
        return root;
      };
      wrappedAttachShadow.__psmCleanupHotfixWrapped = true;
      Element.prototype.attachShadow = wrappedAttachShadow;
    }
  } catch {}

  function start() {
    observeRoot(document);

    if (document.documentElement) {
      inspectExisting(document);
      discoverShadowRoots(document.documentElement);
    }

    setTimeout(() => {
      stopped = true;
      for (const observer of observers) {
        try { observer.disconnect(); } catch {}
      }
      observers.length = 0;
    }, ACTIVE_FOR_MS);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start, { once: true });
  } else {
    start();
  }
})();
